-- Архив сезонов (24.11): итоги прошлых сезонов для переключателя сезона в «Таблице» и «Правилах» (docs/site.md).
-- Сезон здесь — готовый снимок, движок его не пересчитывает: общий зачёт (с очками за места по неделям), сетка кубка, положение.
-- 2025 — из таблицы Комиссии: листы «2025 Общий зачет», «2025 кубок», «2025 Регламент» (выгрузка 24.11.2026).
create table public.season_archive (
  season int primary key,
  standings jsonb not null,   -- [{nick, total, baths, u, uu, long, k, week_pts: {неделя: очки за место}}]
  cup jsonb,                  -- {winners: [ник], rounds: [{title, note, groups: [[{p: [ники], s: [очки]}]]}]}
  rules jsonb                 -- {title, items: [пункт положения]}
);
alter table public.season_archive enable row level security;
create policy "архив сезонов виден всем" on public.season_archive for select using (true);
revoke all on public.season_archive from anon, authenticated;
grant select on public.season_archive to anon, authenticated;
grant all on public.season_archive to service_role;

