  $arch${"winners":["Хвост","Денис"],"rounds":[{"title":"Раунд 1","groups":[[{"p":["Витёк","Ахмед"],"s":[2,2]},{"p":["Леха","Alex B"],"s":[14,11]}],[{"p":["Шурик","Махмуд"],"s":[4,2]},{"p":["Ден","Король"],"s":[9,6]}],[{"p":["Диман","Даня"],"s":[11,2]},{"p":["Арс","Женёк В"],"s":[2,6]}],[{"p":["Фил","Данюс"],"s":[44,16]},{"p":["Хвост","Денис"],"s":[30,29]}]]},{"title":"Раунд 2 · чемпионы","note":"напарники сохраняются","groups":[[{"p":["Леха","Alex B"],"s":[14,6]},{"p":["Ден","Король"],"s":[9,5]}],[{"p":["Диман","Даня"],"s":[3,1]},{"p":["Фил","Данюс"],"s":[7,0]}]]},{"title":"Раунд 2 · ебланы","note":"слепая жеребьёвка ебланов","groups":[[{"p":["Ахмед","Витёк"],"s":[0,2]},{"p":["Хвост","Денис"],"s":[7,2]}],[{"p":["Женёк В","Арс"],"s":[4,2]},{"p":["Шурик","Махмуд"],"s":[20,1]}]]},{"title":"Раунд 3 · чемпионы","note":"напарники сохраняются","groups":[[{"p":["Леха","Alex B"],"s":[18,1]},{"p":["Фил","Данюс"],"s":[21,9]}]]},{"title":"Раунд 3 · ебланы","note":"слепая жеребьёвка новых ебланов","groups":[[{"p":["Хвост","Денис"],"s":[36,22]},{"p":["Шурик","Махмуд"],"s":[18,7]},{"p":["Даня","Король"],"s":[10,0]},{"p":["Ден","Диман"],"s":[21,26]}]]},{"title":"Финал","note":"напарники сохраняются","groups":[[{"p":["Фил","Данюс"],"s":[7,21]},{"p":["Хвост","Денис"],"s":[16,18]}]]}]}$arch$::jsonb,
  $arch${"title":"Положение о третьем чемпионате ЕБЛ","items":["Чемпионат ЕБЛ — ежегодное соревнование, проводящееся Евразийской банной лигой (ЕБЛ) с целью популяризации бань, саун и apres-ban'.","В чемпионате принимают участие все участники группы ОУД. В чемпионате не могут принимать участие другие участники. Если участник вступает в группу ОУД в середине года, очки в зачет чемпионата ЕБЛ начинают ему начисляться с этого момента. Если участник покидает группу ОУД, очки в зачет чемпионата ЕБЛ перестают ему начисляться с этого момента.","Под баней понимается специализированное для термических процедур, нагретое выше 50 °C помещение, в котором участник пребывает в раздетом виде. К баням относятся как общественные (городские) бани, так и индивидуальные банные помещения, включая ночные сауны, фитнесы и аквапарки с саунами, домашние сауны и переносные (разборные) бани.","Очки в чемпионате ЕБЛ начисляются за поход в баню. Очки за данный поход начисляются игроку при выполнении следующих условий: 1) поход в баню длился не менее 1 часа, 2) это был первый поход в данную баню за данные сутки, 3) поход документирован постом любого из участников чемпионата в телеграм-группу в тот же день.","Подсчет очков проводится еженедельно. Баня попадает в неделю, если участник зашел в нее не позднее 22:59 МСК воскресенья и прислал в этот же день информацию в группу. В случае, если информация о походе в баню прислана позже указанного срока, она попадает в следующую неделю.","По каждому игроку каждую неделю подсчитывается количество посещенных бань. Участники ранжируются по убыванию в зависимости от общего количества посещенных бань за неделю. Участнику, занявшему первое место, начисляется 10 очков, второе место — 7 очков, третье место — 5 очков, четвертое место — 3 очка, пятое место — 2 очка, шестое место — 1 очко. Участникам, занявшим седьмое и последующее места, начисляется 0 очков. В случае, если участники поделили места, им начисляется среднее арифметическое от количества баллов за эти места с округлением до десятых. Например, если 4 участника заняли 5—8 места, им начисляются по (2 + 1 + 0 + 0)/4 = 0,8 очков. Участники, не посетившие ни одной бани, получают 0 очков.","В случае, если ни один из участников за неделю не посетил ни одной из бань, неделя исключается из розыгрыша.","Кроме того, очки начисляются за факт посещения бани. За каждое посещение бани участнику начисляется 1 очко. Очки получают в т. ч. те участники, которые получили 0 очков в розыгрыше общего количества бань.","В случае, если баня посещена группой, в которую входит от 3 до 5 участников ЕБЛ, каждому участнику за такое посещение дополнительно начисляется по 1 очку (категория К). Если в группе от 6 до 8 человек, каждому её участнику начисляется по 2 очка (категория КК), 9 человек и выше — по 3 очка. Посещение считается групповым, если участники были в бане в пределах календарных суток по московскому времени.","Дополнительно подсчитывается количество посещенных каждым участником уникальных бань. Уникальными считаются бани, размещенные в разных зданиях, а также бани, размещенные в одном здании, но считающиеся разными разрядами (каждый разряд снабжен отдельным входом по отдельному билету). Банные помещения одного аквапарка/фитнеса считаются одной баней (одним разрядом). За каждую уникальную (в пределах 2025 года) посещенную баню участник получает еще 1 очко (т. е. суммарно за посещение такой бани в первый раз участник получает 2 очка).","Также очки начисляются за посещение ультрауникальных бань — тех, в которых ни один из участников ЕБЛ ранее не был в 2023—2025 гг. За ультрауникальную баню каждый из участников, посетивших ее группой впервые (в пределах одного дня) в ЕБЛ, получает еще одно очко. За такое посещение бани участник суммарно получит 3 очка (не считая коллективных начислений).","Участник получает +1 очко в случае, если документально подтверждает свое пребывание в бане длительностью более 150 минут. Документальными свидетельствами являются фотографии участника, банного интерьера и экстерьера, снабженные выполненными вручную или автоматически (с помощью средств социальной сети) отметками о времени входа и выхода. Бани без двойной отметки воспринимаются как посещенные на 1 час, за них начисляется только 1 очко. При групповом посещении бани каждый участник должен самостоятельно озаботиться документированием своего посещения.","Очки каждого участника за все недели в течение года складываются.","Победителем чемпионата объявляется участник, набравший максимальное количество очков в течение года. В случае равенства этого показателя победитель выявляется по дополнительному показателю — количеству посещенных в течение года бань.","Чемпионат длится с 1 января 2025 года по 31 декабря 2025 года. Недели 1-5 января и 29-31 декабря дает баллы за места наравне с остальными неделями.","Все спорные ситуации разбираются на комиссии чемпионата ЕБЛ, проводящейся периодически в Василёвских банях. О дате проведения очередной комиссии участники чемпионата ЕБЛ извещаются по телеграм-каналу ОУД.","Турнирную таблицу ведет участник, уполномоченный комиссией чемпионата ЕБЛ."]}$arch$::jsonb);

-- какие сезоны есть в архиве — в первом запросе сайта (сам архив сайт берёт по выбору сезона)
create or replace function public.boot_public(apikey text default null) returns json
language sql stable
set search_path = ''
as $$
  select json_build_object(
    'baths', public.baths_all(),
    'counts', public.bath_counts_all(),
    'standings', (select coalesce(json_agg(s order by s.nick), '[]'::json) from public.standings s),
    'reviews', (select coalesce(json_agg(json_build_object('id', r.id, 'bath_id', r.bath_id, 'rating', r.rating, 'text', r.text,
                  'created_at', r.created_at, 'player_id', r.player_id, 'players', case when p.id is null then null else json_build_object('nick', p.nick) end)
                  order by r.id), '[]'::json)
                from public.reviews r left join public.players p on p.id = r.player_id),
    'prices', (select coalesce(json_agg(json_build_object('id', x.id, 'bath_id', x.bath_id, 'price', x.price, 'currency', x.currency,
                 'duration_min', x.duration_min, 'is_weekend', x.is_weekend, 'before_time', x.before_time, 'price_date', x.price_date)
                 order by x.bath_id, x.price_date, x.id), '[]'::json)
               from public.bath_prices x),
    'beer', (select coalesce(json_agg(json_build_object('id', x.id, 'bath_id', x.bath_id, 'price', x.price, 'currency', x.currency, 'price_date', x.price_date)
               order by x.bath_id, x.price_date, x.id), '[]'::json)
             from public.bath_beer_prices x),
    'players', (select coalesce(json_agg(json_build_object('id', p.id, 'nick', p.nick, 'is_commission', p.is_commission, 'photo_url', p.photo_url)
                  order by p.id), '[]'::json)
                from public.players p),
    'cup', public.cup_state(),
    'week_posts', public.week_posts_public(),
    'seasons', (select coalesce(json_agg(a.season order by a.season desc), '[]'::json) from public.season_archive a)
  )
$$;
